insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25520')::uuid, md5('building-papenreye-51-55-22453')::uuid, '25520', 'preiswertes-buero-zwischen-eppendorf-und-flughafen-25520', 'Preiswertes Büro zwischen Eppendorf und Flughafen', 'Der aufwendig modernisierte Gewerbehof Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und dem Flughafen Fuhlsbüttel. Die nahegelegene Bushaltestelle …', 'Der aufwendig modernisierte Gewerbehof Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und dem Flughafen Fuhlsbüttel. Die nahegelegene Bushaltestelle Spreenende gewährleistet eine gute Anbindung an den ÖPNV. Zahlreiche Geschäfte des täglichen Bedarfs sowie Cafes und Restaurants sind fußläufig erreichbar. Die hier angebotene Gewerbefläche ist vielseitig nutzbar und wird aktuell als reine Bürofläche genutzt. Zur Ausstattung zählen neben einem repräsentativen Eingangsbereich und einer Rampenandienung glatt gespachtelte Decken und Wände, teilweise Glaselemente in den Wänden und Glastüren, innenliegender Blendschutz an den Fenstern, eine vollständig ausgestattete Teeküche sowie getrennte WC-Anlagen. PKW-Stellplätze können unmittelbar am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 15, 469, 'https://www.buerohamburg.de/objects/pdf/BHI_25520.pdf', null, 'filemaker', '25520') on conflict (id) do nothing;
