insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22157')::uuid, md5('building-harburger-schlossstrasse-18-28-21079')::uuid, '22157', 'flexibel-gestaltbare-bueroflaeche-mit-balkon-im-harburger-binnenhafen-22157', 'Flexibel gestaltbare Bürofläche mit Balkon im Harburger Binnenhafen', 'Die Channel 1-4 sind vier einzelne Gebäude, die zwischen 1999 und 2001 gebaut wurden und befinden sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung …', 'Die Channel 1-4 sind vier einzelne Gebäude, die zwischen 1999 und 2001 gebaut wurden und befinden sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie die Harburger Altstadt. Jedes dieser viergeschossigen Objekte erschließt sich über einen repräsentativen Eingangsbereich. Die geplante Ausstattung der Bürofläche soll unter anderem eine Grundbeleuchtung, einen hochwertigen Bodenbelag, innenliegenden Blendschutz, einen EDV Raum, eine funktionale Teeküche sowie separate sanitäre Einheiten umfassen. Die weitere Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenbilder sind beispielhaft gewählt und stammen aus einer Mietfläche im Objekt. PKW-Stellplätze können nach Absprache auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'barrierefrei', 'stellplaetze']::text[], 260, 1600, 'https://www.buerohamburg.de/objects/pdf/BHI_22157.pdf', null, 'filemaker', '22157') on conflict (id) do nothing;
