insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23421')::uuid, md5('building-millerntorplatz-1-20359')::uuid, '23421', 'st-pauli-modernes-buero-am-millerntor-23421', 'St. Pauli: Modernes Büro am Millerntor', 'Der imposante Gebäudekomplex befindet sich zwischen der City und St. Pauli in prominenter Nachbarschaft zwischen dem Hamburger-Dom-Areal und den Tanzenden Türmen. Das lebendige …', 'Der imposante Gebäudekomplex befindet sich zwischen der City und St. Pauli in prominenter Nachbarschaft zwischen dem Hamburger-Dom-Areal und den Tanzenden Türmen. Das lebendige Umfeld ist geprägt durch zahlreiche Cafés und Restaurants sowie zahlreiche Geschäfte des täglichen Bedarfs. Die Anbindung an den ÖPNV ist durch die nur wenige Meter entfernte U-Bahnstation St. Pauli sowie diverse umliegende Bushaltestellen als sehr gut zu bezeichnen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23421-1')::uuid, md5('property-23421')::uuid, 'Mietfläche', 474, 18, null, 'filemaker', '23421-1') on conflict (id) do nothing;
