insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20190')::uuid, md5('building-alter-teichweg-25-22081')::uuid, '20190', 'individuelles-bueroloft-am-osterbekkanal-20190', 'Individuelles Büroloft am Osterbekkanal', 'Das alte Fabrikgebäude wurde im Jahr 2000 aufwändig restauriert und modernisiert und liegt unmittelbar am Osterbekkanal. Die Anbindung an den ÖPNV ist durch verschiedene Buslinien …', 'Das alte Fabrikgebäude wurde im Jahr 2000 aufwändig restauriert und modernisiert und liegt unmittelbar am Osterbekkanal. Die Anbindung an den ÖPNV ist durch verschiedene Buslinien und die fußläufig schnell erreichbaren U-Bahnstationen Barmbek und Alter Teichweg gesichert. Die helle Bürofläche befindet sich im Erdgeschoss. Teppichboden und Vinylboden in Holzoptik, glatt gespachtelte Wände und Decken, bodentiefe Fenster und ein direkter Zugang zum Lastenaufzug unterstreichen den industriellen Charakter dieser besonderen Bürofläche. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'erdgeschoss', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_20190.pdf', null, 'filemaker', '20190') on conflict (id) do nothing;
