insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23343')::uuid, md5('building-bei-st-annen-2-20457')::uuid, '23343', 'hochwertig-ausgebaute-bueroflaeche-in-der-speicherstadt-23343', 'Hochwertig ausgebaute Bürofläche in der Speicherstadt', 'Die Speicherstadt befindet sich zwischen der Hamburger Innenstadt und der HafenCity und besticht durch ihren besonderen Flair mit historischen Kontorhäusern und zahlreichen …', 'Die Speicherstadt befindet sich zwischen der Hamburger Innenstadt und der HafenCity und besticht durch ihren besonderen Flair mit historischen Kontorhäusern und zahlreichen Fleeten. Der Anschluss an das öffentliche Verkehrsnetz ist durch diverse Buslinien gesichert. Zahlreiche Einkaufsmöglichkeiten und eine Vielzahl an Cafés und Restaurants im direkten Umfeld sind fußläufig schnell erreicht. Die Bürofläche erschließt sich sowohl über einen Personenaufzug als auch über einen Paternoster. Zur hochwertigen Ausstattung zählen teilweise Glastrennwände, Kühlung in einigen Räumen, Glasfaseranschluss,  innenliegender Sonnenschutz, Teppich- und Amtikoböden sowie Küchen und separate WC-Einheiten. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze', 'wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_23343.pdf', null, 'filemaker', '23343') on conflict (id) do nothing;
