insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-17620')::uuid, md5('building-schnackenburgallee-43-45-22525')::uuid, '17620', 'modernes-buero-im-hamburger-westen-an-der-a7-17620', 'Modernes Büro im Hamburger Westen an der A7', 'Der markante Neubau befindet sich in verkehrsgünstiger Lage unweit der Autobahnauffahrt Volkspark, der direkten Anbindung an die A7. Die modernen Büroflächen erschließen sich über …', 'Der markante Neubau befindet sich in verkehrsgünstiger Lage unweit der Autobahnauffahrt Volkspark, der direkten Anbindung an die A7. Die modernen Büroflächen erschließen sich über ein helles Foyer mit einem Personenaufzug und sind bereits mit einem Teppichbodenbelag, einer CAT-7 Verkabelung in Bodentanks, außenliegendem, elektrischen Sonnenschutz, einem Beleuchtungskonzept mit Pendelleuchten, einer Pantry und separaten WC-Einheiten ausgestattet. Die Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können auf dem Hof angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 440, 920, 'https://www.buerohamburg.de/objects/pdf/BHI_17620.pdf', null, 'filemaker', '17620') on conflict (id) do nothing;
