insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16023')::uuid, md5('building-ueberseeallee-1-3-20457')::uuid, '16023', 'bereit-fuer-neue-dimensionen-das-sumatrakontor-in-der-hafencity-16023', 'Bereit für neue Dimensionen - das Sumatrakontor in der HafenCity', 'Das moderne Büro- und Geschäftsgebäude Sumatrakontor befindet sich in markanter Ecklage im angesagten Stadtteil HafenCity gegenüber des neuen EKZs Westfiel-Quartier. Berühmte …', 'Das moderne Büro- und Geschäftsgebäude Sumatrakontor befindet sich in markanter Ecklage im angesagten Stadtteil HafenCity gegenüber des neuen EKZs Westfiel-Quartier. Berühmte Sehenswürdigkeiten sowie zahlreiche Restaurants und Cafés befinden sich im direkten Umfeld. Die nahe gelegene U4-Haltestelle sorgt für eine gute Anbindung an das öffentliche Verkehrsnetz.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-16023-1')::uuid, md5('property-16023')::uuid, 'Mietfläche', 481, 25, null, 'filemaker', '16023-1') on conflict (id) do nothing;
