insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23617')::uuid, md5('building-ferdinandstrasse-29-33-20095')::uuid, '23617', 'gepflegte-bueroflaeche-im-klassischem-kontorhaus-mit-terrasse-23617', 'Gepflegte Bürofläche im klassischem Kontorhaus mit Terrasse', 'Das hochwertig ausgebaute Kontorhaus befindet sich in zentraler Lage zwischen Ballindamm und Mönckebergstraße. Die Binnenalster, das Rathaus und die Innenstadt mit zahlreichen …', 'Das hochwertig ausgebaute Kontorhaus befindet sich in zentraler Lage zwischen Ballindamm und Mönckebergstraße. Die Binnenalster, das Rathaus und die Innenstadt mit zahlreichen Flaniermeilen und Einkaufsstraßen sind fußläufig schnell erreicht. Die Anbindung an den ÖPNV ist durch den nahe gelegenen Hauptbahnhof gesichert. Die aktuelle Ausstattung der Mietfläche umfasst u.a. Teppichbodenbelag, integrierte Deckenbeleuchtung, eine eingerichtete Pantry sowie separate, moderne WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Highlight ist eine ca. 29 qm große Terrasse, welche zur oben genannten Mietfläche dazu addiert wird. PKW-Stellplätze können im direkten Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse']::text[], 186, 658, 'https://www.buerohamburg.de/objects/pdf/BHI_23617.pdf', null, 'filemaker', '23617') on conflict (id) do nothing;
