insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24732')::uuid, md5('building-harkortstrasse-79-22765')::uuid, '24732', 'loftige-bueroflaeche-in-zentraler-lage-von-altona-24732', 'Loftige Bürofläche in zentraler Lage von Altona', 'Das modernisierte Rotklingergebäude befindet sich in markanter Ecklage des Neubau-Quartiers Neue Mitte Altona. Der U- und S-Bahnhof Altona mit zusätzlicher Anbindung an zahlreiche …', 'Das modernisierte Rotklingergebäude befindet sich in markanter Ecklage des Neubau-Quartiers Neue Mitte Altona. Der U- und S-Bahnhof Altona mit zusätzlicher Anbindung an zahlreiche Buslinien ist in wenigen Gehminuten erreicht und gewährleistet eine hervorragende Anbindung an den ÖPNV. Diverse Einkaufsmöglichkeiten und alles Geschäfte des täglichen Bedarfs liegen im direkten Umfeld.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24732-1')::uuid, md5('property-24732')::uuid, 'Mietfläche', 481, 18.5, null, 'filemaker', '24732-1') on conflict (id) do nothing;
