insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19264')::uuid, md5('building-ueberseering-29-22297')::uuid, '19264', 'frei-gestaltbare-bueroflaeche-mit-sehr-guter-verkehrsanbindung-19264', 'Frei gestaltbare Bürofläche mit sehr guter Verkehrsanbindung', 'Die City-Nord gehört zu den bekanntesten und wichtigsten Bürostandorten Hamburgs. Nicht nur die gute Anbindung an den ÖPNV und den Flughafen, sondern auch die unmittelbare Nähe …', 'Die City-Nord gehört zu den bekanntesten und wichtigsten Bürostandorten Hamburgs. Nicht nur die gute Anbindung an den ÖPNV und den Flughafen, sondern auch die unmittelbare Nähe zum Stadtpark machen diese Lage attraktiv. Die helle Bürofläche ist unter anderem mit Teppichboden, getrennten WC-Einheiten sowie einer Teeküche ausgestattet und werden über einen Personenaufzug erschlossen. Die Raumaufteilung und Gestaltung der Bürofläche ist in Absprache mit dem zukünftigen Mieter möglich. Der Mietpreis variiert je nach Ausbauwunsch. Die Innenansichten sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Objekt. PKW- Stellplätze können zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 114, 937, 'https://www.buerohamburg.de/objects/pdf/BHI_19264.pdf', null, 'filemaker', '19264') on conflict (id) do nothing;
