insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25083')::uuid, md5('building-eiffestrasse-74-80-20537')::uuid, '25083', 'borgfelde-bueroflaeche-in-verkehrsguenstiger-lage-der-city-sued-25083', 'Borgfelde: Bürofläche in verkehrsgünstiger Lage der City-Süd', 'Das Büro- und Geschäftsgebäude befindet sich unmittelbar am Mittelkanal, unweit der U- und S-Bahnstation Berliner Tor. Über die nahegelegenen Elbbrücken sind die Autobahnen A1, A7 …', 'Das Büro- und Geschäftsgebäude befindet sich unmittelbar am Mittelkanal, unweit der U- und S-Bahnstation Berliner Tor. Über die nahegelegenen Elbbrücken sind die Autobahnen A1, A7 und A24 schnell erreicht. Das Gebäude verfügt über Personen- und Lastenaufzüge. Die helle Bürofläche kann nach den individuellen Wünschen des neuen Mieters ausgebaut und ausgestattet werden. PKW-Stellplätze können in der hauseigenen Tiefgarage sowie auf dem Hof angemietet werden. Die Innenansichten sind beispielhaft gewählt und stammen aus einer anderen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], 240, 505, 'https://www.buerohamburg.de/objects/pdf/BHI_25083.pdf', null, 'filemaker', '25083') on conflict (id) do nothing;
