insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25057')::uuid, md5('building-zirkusweg-2-20359')::uuid, '25057', 'st-pauli-hochwertige-bueroflaeche-im-astraturm-mit-grosser-terrasse-25057', 'St.Pauli: Hochwertige Bürofläche im Astraturm mit großer Terrasse', 'Der Zirkusweg befindet sich unweit der Elbe und der Hafenstraße zwischen den Landungsbrücken und dem Hamburger Fischmarkt. Zahlreiche Cafés und Restaurants im Umfeld sind …', 'Der Zirkusweg befindet sich unweit der Elbe und der Hafenstraße zwischen den Landungsbrücken und dem Hamburger Fischmarkt. Zahlreiche Cafés und Restaurants im Umfeld sind fußläufig ebenso schnell erreicht wie die U-Bahn Haltestelle St. Pauli. Der markante Neubau zählt zu den höchsten Bauwerken Hamburgs und ist durch das innovative Beleuchtungskonzept auch bei Dunkelheit weit sichtbar. Die einzelnen Geschosse erschließen sich über ein großzügiges Entrée mit Conciergeservice und mehreren Aufzügen. Die moderne und hochwertige Ausstattung der Büroeinheiten umfasst bodentiefe Fensterelemente, teilweise Glastrennwände, Stehleuchten und Bodentanks für eine Netzwerkverkabelung. Highlight dieser Fläche ist eine ca. 105 qm große umlaufende Terrasse mit Elbblick, welche zum oben genannten Mietpreis in die Gesamtmiete mit einfließt. Pkw-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 486, 644, 'https://www.buerohamburg.de/objects/pdf/BHI_25057.pdf', null, 'filemaker', '25057') on conflict (id) do nothing;
