insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22016')::uuid, md5('building-gerhofstrasse-19-20354')::uuid, '22016', 'moderne-bueroflaeche-mit-terrasse-in-zentraler-innenstadtlage-22016', 'Moderne Bürofläche mit Terrasse in zentraler Innenstadtlage', 'Das repräsentative Büro- und Geschäftsgebäude befindet sich unmittelbar am Gänsemarkt im Herzen der Hamburger Innenstadt. Cafés, Restaurants und alle Geschäfte des täglichen …', 'Das repräsentative Büro- und Geschäftsgebäude befindet sich unmittelbar am Gänsemarkt im Herzen der Hamburger Innenstadt. Cafés, Restaurants und alle Geschäfte des täglichen Bedarfs sind im direkten Umfeld zu finden. Die U- und S-Bahnstationen Jungfernstieg sowie Gänsemarkt sind nach wenigen Minuten erreicht. PKW-Stellplätze können in den umliegenden Parkhäusern angemietet werden. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-22016-1')::uuid, md5('property-22016')::uuid, 'Mietfläche', 490, 26, null, 'filemaker', '22016-1') on conflict (id) do nothing;
