insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24292')::uuid, md5('building-harburger-schlossstrasse-30-21079')::uuid, '24292', 'der-channel-im-harburger-binnenhafen-24292', 'Der Channel im Harburger Binnenhafen', 'Der architektonisch ansprechende Channel 8 wurde 2002 gebaut und befindet sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 …', 'Der architektonisch ansprechende Channel 8 wurde 2002 gebaut und befindet sich in verkehrsgünstiger Lage im Harburger Binnenhafen mit einer guten Anbindung an die Autobahnen A1 und A7 sowie die Harburger Altstadt. Die  Ausstattung der Bürofläche soll unter anderem eine Grundbeleuchtung, einen hochwertigen Bodenbelag, innenliegenden Blendschutz, einen EDV Raum, eine funktionale Teeküche sowie separate sanitäre Einheiten umfassen. Die weitere Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können nach Absprache auf dem Gelände angemietet werden. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer anderen Mietfläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 260, 1600, 'https://www.buerohamburg.de/objects/pdf/BHI_24292.pdf', null, 'filemaker', '24292') on conflict (id) do nothing;
