insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23767')::uuid, md5('building-suedportal-1-5-22848')::uuid, '23767', 'moderne-bueroflaeche-im-nord-port-tower-in-flughafennaehe-23767', 'Moderne Bürofläche im Nord-Port-Tower in Flughafennähe', 'Das Objekt befindet sich im Gewerbegebiet Norderstedt in unmittelbarer Nähe zum Flughafen. Die Anbindung an den ÖPNV ist durch zwei Buslinien gesichert. Auch der Anschluss an die …', 'Das Objekt befindet sich im Gewerbegebiet Norderstedt in unmittelbarer Nähe zum Flughafen. Die Anbindung an den ÖPNV ist durch zwei Buslinien gesichert. Auch der Anschluss an die Autobahn A7 ist in wenigen Fahrminuten erreicht. Der moderne Bürokomplex verfügt über Personenaufzüge und ist aktuell mit einer Verkabelung in Hohlraumböden, Teppichbodenbelag, bodentiefen Fenstern, innenliegendem Sonnenschutz, mechanische Be- und Entlüftung, Stehleuchten, einer Teeküche und separaten WC-Einheiten ausgestattet. PKW Stellplätze stehen im Hof zur Anmietung bereit. Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 195, 495, 'https://www.buerohamburg.de/objects/pdf/BHI_23767.pdf', null, 'filemaker', '23767') on conflict (id) do nothing;
