insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22578')::uuid, md5('building-wendenstrasse-375-379-20537')::uuid, '22578', 'flexibel-gestaltbare-bueroflaeche-22578', 'Flexibel gestaltbare Bürofläche', 'Das markante Bürogebäude befindet sich in ruhiger City-Süd-Lage zwischen Grevenweg und Eiffestraße, unweit der Elbbrücken und der U-Bahnstation Burgstraße. Das Gebäude verfügt …', 'Das markante Bürogebäude befindet sich in ruhiger City-Süd-Lage zwischen Grevenweg und Eiffestraße, unweit der Elbbrücken und der U-Bahnstation Burgstraße. Das Gebäude verfügt über einen ansprechenden Eingangsbereich sowie zwei Personenaufzüge und einen Lastenaufzug, welcher über eine Rampe angedient werden kann. Die vakante Fläche kann nach Rücksprache mit dem Vermieter individuell aufgeteilt und ausgebaut werden. Zur Ausstattung zählen eine Pantry, Teppichboden sowie getrennte WC-Bereiche. PKW-Stellplätze können in der hauseigenen Tiefgarage oder im Hinterhof angemietet werden. Die Innenbilder stammen aus einer frisch renovierten Einheit im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 496, 1145, 'https://www.buerohamburg.de/objects/pdf/BHI_22578.pdf', null, 'filemaker', '22578') on conflict (id) do nothing;
