insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19440')::uuid, md5('building-grosse-elbstrasse-145a-f-22767')::uuid, '19440', 'das-elbkaihaus-loftflaechen-mit-elbblick-und-balkon-19440', 'Das Elbkaihaus - Loftflächen mit Elbblick und Balkon', 'Das Elbkaihaus befindet sich in bester Elblage mit direktem Hafenblick. Der nahe gelegene Bahnhof Altona sichert eine gute Anbindung an den ÖPNV. Diverse Einkaufsmöglichkeiten, …', 'Das Elbkaihaus befindet sich in bester Elblage mit direktem Hafenblick. Der nahe gelegene Bahnhof Altona sichert eine gute Anbindung an den ÖPNV. Diverse Einkaufsmöglichkeiten, Cafés und Restaurants sind fußläufig schnell erreicht. Die helle und transparent gestaltete Mietfläche ist unter anderem mit einem hochwertigem Fußbodenbelag, außen liegendem Sonnenschutz, teilweise innen liegendem Blendschutz, Trennwänden in einer Stahl- und Glaskonstruktion, einem Hohlraumboden für die bereits verlegte CAT-Verkabelung, einem schlüssigen Beleuchtungssystem, separaten WC-Einheiten, einer Pantry und einer Gegensprech- und Sprinkleranlage ausgestattet. Die Innenansichten sind beispielhaft gewählt. PKW-Stellplätze können direkt am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze', 'wasserblick']::text[], 131, 498, 'https://www.buerohamburg.de/objects/pdf/BHI_19440.pdf', null, 'filemaker', '19440') on conflict (id) do nothing;
