insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22876')::uuid, md5('building-deichstrasse-11-20459')::uuid, '22876', 'altstadt-kompakte-bueroflaeche-gegenueber-der-speicherstadt-22876', 'Altstadt: Kompakte Bürofläche gegenüber der Speicherstadt', 'Die Deichstraße liegt im historischen Altstadtbereich zwischen HafenCity und Nikolaikirche. Die U-Bahnstation Rödingsmarkt und diverse Bushaltestellen sichern einen sehr guten …', 'Die Deichstraße liegt im historischen Altstadtbereich zwischen HafenCity und Nikolaikirche. Die U-Bahnstation Rödingsmarkt und diverse Bushaltestellen sichern einen sehr guten Anschluss an den öffentlichen Nahverkehr. Der Rathausmarkt mit vielseitigen Einkaufsmöglichkeiten, zahlreichen Cafés sowie Restaurants ist fußläufig ebenso wie die belebte Mönckebergstraße schnell erreicht. Das ein Foyer mit Personenaufzug. Die Mietfläche wird in Absprache mit dem zukünftigen Mieter neu aufgeteilt und mit einem neuen Bodenbelag ausgestattet. Auch die Sanitäreinheiten und die Küchen werden saniert. Das Objekt verfügt über einen außenliegenden Sonnenschutz sowie einen Glasfaseranschluss. PKW-Stellplätze können in der hauseigenen Tiefgarage nach Rücksprache angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze', 'wasserblick']::text[], 250, 750, 'https://www.buerohamburg.de/objects/pdf/BHI_22876.pdf', null, 'filemaker', '22876') on conflict (id) do nothing;
