insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24297')::uuid, md5('building-haubachstrasse-86-22765')::uuid, '24297', 'bezugsfertiges-buero-in-attraktiver-lage-von-altona-24297', 'Bezugsfertiges Büro in attraktiver Lage von Altona', 'Das Geschäftshaus befindet sich in verkehrsgünstiger Lage im Hamburger Westen, nur wenige Meter von der U-Bahnstation Holstenstraße entfernt. Das Theater Neue Flora sowie …', 'Das Geschäftshaus befindet sich in verkehrsgünstiger Lage im Hamburger Westen, nur wenige Meter von der U-Bahnstation Holstenstraße entfernt. Das Theater Neue Flora sowie Einkaufsmöglichkeiten sind ebenfalls nur wenige Meter entfernt. Zur aktuellen Ausstattung der hellen Fläche zählen unter anderem Teppichfußboden, eine Cat-7-Verkabelung, außenliegender Sonnenschutz, getrennte WC-Einheiten sowie eine großzügige, voll ausgestattete Pantry. Im Keller liegt bereits ein Glasfaseranschluss, der bei Bedarf in die Fläche gelegt werden kann. Es besteht die Möglichkeit, sowohl auf den Hof als auch in die hauseigenen Tiefgarage Pkw-Stellplätze anzumieten.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_24297.pdf', null, 'filemaker', '24297') on conflict (id) do nothing;
