insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-3633')::uuid, md5('building-jessenstrasse-4-6-22767')::uuid, '3633', 'helle-bueroflaeche-mitten-in-altona-3633', 'Helle Bürofläche mitten in Altona', 'Das Bürogebäude befindet sich im Herzen von Altona in unmittelbarer Nähe zum gleichnamigen S- und Fernbahnhof sowie der S-Bahnstation Königstraße. Vielfältige …', 'Das Bürogebäude befindet sich im Herzen von Altona in unmittelbarer Nähe zum gleichnamigen S- und Fernbahnhof sowie der S-Bahnstation Königstraße. Vielfältige Einkaufsmöglichkeiten des täglichen Bedarfs sowie diverse Restaurants befinden sich in unmittelbarer Umgebung. Das Gebäude erhielt im Zuge umfassender Umbaumaßnahmen u.a. einen neuen Eingangsbereich sowie eine übersichtliche Beschilderung. Die Mietfläche ist über zwei Personenaufzüge zu erreichen und kann in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Der Mietpreis richtet sich nach den individuellen Ausstattungswünschen. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.Die Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 176, 513, 'https://www.buerohamburg.de/objects/pdf/BHI_3633.pdf', null, 'filemaker', '3633') on conflict (id) do nothing;
