insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25470')::uuid, md5('building-jessenstrasse-4-6-22767')::uuid, '25470', 'helle-bueroflaeche-im-herzen-altonas-25470', 'Helle Bürofläche im Herzen Altonas', 'Das Bürogebäude befindet sich im Herzen von Altona in unmittelbarer Nähe zum gleichnamigen S- und Fernbahnhof sowie der S-Bahnstation Königstraße. Vielfältige …', 'Das Bürogebäude befindet sich im Herzen von Altona in unmittelbarer Nähe zum gleichnamigen S- und Fernbahnhof sowie der S-Bahnstation Königstraße. Vielfältige Einkaufsmöglichkeiten des täglichen Bedarfs sowie diverse Restaurants befinden sich in unmittelbarer Umgebung. Das Gebäude erhielt im Zuge umfassender Umbaumaßnahmen u.a. einen neuen Eingangsbereich sowie eine übersichtliche Beschilderung. Die Mietfläche ist über zwei Personenaufzüge zu erreichen und kann in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Der Mietpreis richtet sich nach den individuellen Ausstattungswünschen. Die Innenansichten sind beispielhaft gewählt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 176, 513, 'https://www.buerohamburg.de/objects/pdf/BHI_25470.pdf', null, 'filemaker', '25470') on conflict (id) do nothing;
