insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24285')::uuid, md5('building-borselstrasse-16-22765')::uuid, '24285', 'loftige-bueroflaeche-im-urbanen-ottensen-24285', 'Loftige Bürofläche im urbanen Ottensen', 'Der 1902 erbaute Borselhof befindet sich inmitten des lebendigen, kreativen Stadtteils Ottensen zwischen den S-Bahnstationen Ottensen und Altona, nahe den Zeisehallen und der …', 'Der 1902 erbaute Borselhof befindet sich inmitten des lebendigen, kreativen Stadtteils Ottensen zwischen den S-Bahnstationen Ottensen und Altona, nahe den Zeisehallen und der Fabrik. Das Umfeld ist geprägt durch zahlreiche Geschäfte des täglichen Bedarfs sowie diverse Cafés und Restaurants. Die nur wenige Fußminuten entfernte S-Bahnstation Ottensen sorgt für eine sehr gute Anbindung an das öffentliche Verkehrsnetz.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24285-1')::uuid, md5('property-24285')::uuid, 'Mietfläche', 515, 16, null, 'filemaker', '24285-1') on conflict (id) do nothing;
