insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25362')::uuid, md5('building-brodschrangen-3-5-20457')::uuid, '25362', 'herrschaftliche-altbauflaeche-in-lebendiger-innenstadtlage-25362', 'Herrschaftliche Altbaufläche in lebendiger Innenstadtlage', 'Das markante Geschäftsgebäude befindet sich zwischen Rathausmarkt und Willy-Brandt-Straße in attraktiver Hamburger Innenstadtlage. Die Anbindung an den ÖPNV ist durch die …', 'Das markante Geschäftsgebäude befindet sich zwischen Rathausmarkt und Willy-Brandt-Straße in attraktiver Hamburger Innenstadtlage. Die Anbindung an den ÖPNV ist durch die U-Bahnstationen Rathausmarkt und Jungfernstieg sowie diverse Buslinien gesichert. Das Umfeld ist geprägt durch zahlreiche Cafés und Restaurants sowie alle Geschäfte des täglichen Bedarfs. Die vakante Bürofläche wird über einen separaten Eingang erschlossen. Die Ausstattung umfasst hohe Decken, großzügige Fensterelemente, teilweise Stuck im Deckenbereich, teilweise Beleuchtungssysteme, Teppichfußboden und separate WC-Einheiten. PKW-Stellplätze können im Umfeld angemietet werden. Die Bürofläche erstreckt sich vom 5. Obergeschoss bis zum 6. Obergeschoss. Diese Innenbilder sind beispielhaft gewählt und stammen aus einer hochwertig ausgebauten Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 240, 516, 'https://www.buerohamburg.de/objects/pdf/BHI_25362.pdf', null, 'filemaker', '25362') on conflict (id) do nothing;
