insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24300')::uuid, md5('building-gertrudenstrasse-9-20095')::uuid, '24300', 'moderne-bueroflaeche-in-zentraler-innenstadtlage-zur-untermiete-24300', 'Moderne Bürofläche in zentraler Innenstadtlage zur Untermiete', 'Das markante Bürogebäude befindet sich in bester Innenstadtlage zwischen Mönckebgerstraße und Binnenalster. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants …', 'Das markante Bürogebäude befindet sich in bester Innenstadtlage zwischen Mönckebgerstraße und Binnenalster. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants beleben das direkte Umfeld. Der fußläufig schnell erreichte Hauptbahnhof sichert eine hervorragende Verkehrsanbindung an alle S- und U-Bahnanschlüsse und an den Nah- und Fernverkehr der Deutschen Bahn. Die helle Bürofläche erschließt sich über einen gläsernen Personenaufzug. Die aktuelle Ausstattung umfasst Teppichfußboden, bildschirmgerechte Arbeitsplatzbeleuchtung, eine CAT-7-Verkabelung, Hohlraumboden, akustisch wirksame Decken, Glastüren, außen liegenden Sonnenschutz, separate, hochwertige WC-Einheiten und eine Pantry. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Bei dieser Mietfläche handelt es sich um eine Untervermietung bis Ende 2033.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_24300.pdf', null, 'filemaker', '24300') on conflict (id) do nothing;
