insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24717')::uuid, md5('building-christoph-probst-weg-1-4-20251')::uuid, '24717', 'modernes-buero-im-quartier-am-zeughaus-24717', 'Modernes Büro im Quartier am Zeughaus', 'Der moderne Büroneubau im historischen Ambiente befindet sich im westlichen Eppendorf nahe der Universitätsklinik. Flughafennähe, schnelle Anbindung an die Autobahnen sowie eine …', 'Der moderne Büroneubau im historischen Ambiente befindet sich im westlichen Eppendorf nahe der Universitätsklinik. Flughafennähe, schnelle Anbindung an die Autobahnen sowie eine Bushaltestelle direkt vor dem Objekt stellen eine gute Verkehrsanbindung dar. Gastronomische Einrichtungen sind fußläufig bequem in der Mittagspause zu erreichen. Zur exzellenten Ausstattung zählt u.a. die flexible Aufteilung sowohl in Einzel- als auch Team- und Gruppenbüros, sehr hochwertige Materialien, ein Hohlraumboden, eine computergerechte Beleuchtung, ein außen liegender Sonnenschutz sowie eine komplett ausgestattete Teeküche. Der Mietpreis hängt von den individuellen Umbauwünschen des zukünftigen Mieters ab. Diese Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 489, 734, 'https://www.buerohamburg.de/objects/pdf/BHI_24717.pdf', null, 'filemaker', '24717') on conflict (id) do nothing;
