insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16499')::uuid, md5('building-fuhlentwiete-14-20354')::uuid, '16499', 'modernes-buero-in-gefragter-hamburger-geschaeftslage-16499', 'Modernes Büro in gefragter Hamburger Geschäftslage', 'Das markante Bürogebäude befindet sich im Zentrum von Hamburg zwischen dem Gänsemarkt und der Caffamacherreihe. Zahlreiche renommierte Unternehmen sowie diverse, gastronomische …', 'Das markante Bürogebäude befindet sich im Zentrum von Hamburg zwischen dem Gänsemarkt und der Caffamacherreihe. Zahlreiche renommierte Unternehmen sowie diverse, gastronomische Einrichtungen und internationale Modelabels im direkten Umfeld erhöhen die Attraktivität dieser zentralen Innenstadtlage. Der Gänsemarkt mit diversen Buslinien und der U-Bahnstation sichern einen sehr guten Anschluss an den ÖPNV. Das Gebäude verfügt über repräsentative Eingangsfoyers und zwei Erschließungskerne mit Personenaufzügen. Die aktuelle Ausstattung der Bürofläche umfasst einen Teppichbodenbelag, teilweise Glaselemente, Glastüren, Akustikelemente an den Decken, einen Serverraum mit EDV-Verkabelung, eine große Pantry sowie separate WC-Einheiten. PKW-Stellplätze können in der Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_16499.pdf', null, 'filemaker', '16499') on conflict (id) do nothing;
