insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25452')::uuid, md5('building-otto-wels-strasse-49-22297')::uuid, '25452', 'der-stadtpark-turm-zwischen-eppendorf-und-flughafen-25452', 'Der Stadtpark-Turm zwischen Eppendorf und Flughafen', 'Der Stadtpark-Turm befindet sich in unmittelbarer Nähe zum neuen Hamburger Polizeipräsidium. Das Gebäude besticht durch seine moderne Bauform sowie die Nähe zum Hamburger …', 'Der Stadtpark-Turm befindet sich in unmittelbarer Nähe zum neuen Hamburger Polizeipräsidium. Das Gebäude besticht durch seine moderne Bauform sowie die Nähe zum Hamburger Flughafen. Die Anbindung an den ÖPNV ist durch die wenige Meter entfernte U-Bahnstation Alsterdorf als hervorragend zu bezeichnen. Zur Ausstattung gehören ein Hohlraumboden, Teppichboden, ein außenliegender Sonnenschutz, Stehleuchten, bodentiefe Fensterelemente, eine Pantry sowie getrennte WC-Einheiten. Die hier gezeigten Innenansichten stammen aus einer anderen Mietfläche im Objekt. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 236, 1717, 'https://www.buerohamburg.de/objects/pdf/BHI_25452.pdf', null, 'filemaker', '25452') on conflict (id) do nothing;
