insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24284')::uuid, md5('building-flughafenstrasse-52-22335')::uuid, '24284', 'das-airport-center-am-hamburger-flughafen-24284', 'Das Airport Center am Hamburger Flughafen', 'Das Airport Center befindet sich in unmittelbarer Nähe zum Hamburger Flughafen und bietet durch die fußläufig erreichbare U-Bahnstation Fuhlsbüttel Nord eine sehr gute Anbindung …', 'Das Airport Center befindet sich in unmittelbarer Nähe zum Hamburger Flughafen und bietet durch die fußläufig erreichbare U-Bahnstation Fuhlsbüttel Nord eine sehr gute Anbindung an den öffentlichen Nahverkehr. Verschiedene gastronomische Angebote im direkten Umfeld sowie der nahe gelegene Langenhorner Markt mit zahlreichen Geschäften des täglichen Bedarfs sorgen für eine hohe Standortqualität.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24284-1')::uuid, md5('property-24284')::uuid, 'Mietfläche', 530, 14.5, null, 'filemaker', '24284-1') on conflict (id) do nothing;
