insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19869')::uuid, md5('building-dammtorstrasse-33-35-20354')::uuid, '19869', 'hochwertige-altbauflaeche-in-bester-citylage-19869', 'Hochwertige Altbaufläche in bester Citylage', 'Umgeben von renommierten Hamburger Kunst- und Kultureinrichtungen, unweit des Gänsemarktes, befindet sich dieses revitalisierte Altbaugebäude. Die U-Bahnstationen Gänsemarkt und …', 'Umgeben von renommierten Hamburger Kunst- und Kultureinrichtungen, unweit des Gänsemarktes, befindet sich dieses revitalisierte Altbaugebäude. Die U-Bahnstationen Gänsemarkt und Jungfernstieg, der Dammtor-Bahnhof sowie diverse Bushaltestelle im Umfeld sorgen für eine perfekte  Anbindung an das öffentliche Verkehrsnetz. Die vakante Bürofläche wird über einen Personenaufzug erschlossen und verfügt aktuell über Teppichboden, getrennte WC-Einheiten und einer Pantry. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW Stellplätze können in der Tiefgarage des Nachbargebäudes angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_19869.pdf', null, 'filemaker', '19869') on conflict (id) do nothing;
