insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25297')::uuid, md5('building-schopenstehl-15-20095')::uuid, '25297', 'charmante-bueroflaeche-in-zentraler-lage-in-der-hamburger-altstadt-25297', 'Charmante Bürofläche in zentraler Lage in der Hamburger Altstadt', 'Das ansprechende Bürogebäude befindet sich in zentraler, zugleich ruhiger Innenstadtlage in unmittelbarer Nähe zur Speicherstadt. Die U-Bahn-Station Meßberg ist nur wenige …', 'Das ansprechende Bürogebäude befindet sich in zentraler, zugleich ruhiger Innenstadtlage in unmittelbarer Nähe zur Speicherstadt. Die U-Bahn-Station Meßberg ist nur wenige Gehminuten entfernt und gewährleistet eine hervorragende Anbindung an den öffentlichen Nahverkehr. Auch die Mönckebergstraße mit ihren zahlreichen Einkaufs- und Gastronomieangeboten sowie der Hamburger Hauptbahnhof sind schnell erreichbar.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25297-1')::uuid, md5('property-25297')::uuid, 'Mietfläche', 539, 22, null, 'filemaker', '25297-1') on conflict (id) do nothing;
