insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-20121')::uuid, md5('building-mendelssohnstrasse-15-22761')::uuid, '20121', 'ab-sofort-buero-oder-showroom-auf-ruhigem-gewerbehof-in-zentraler-lage-von-bahrenfeld-20121', 'Ab sofort: Büro oder Showroom auf ruhigem Gewerbehof in zentraler Lage von Bahrenfeld', 'Der moderne Gewerbehof Mendelssohnstraße liegt ruhig aber verkehrsgünstig nahe den A7-Anschlussstellen Bahrenfeld und Othmarschen. Die S-Bahnhaltestelle Bahrenfeld ist nach 5 …', 'Der moderne Gewerbehof Mendelssohnstraße liegt ruhig aber verkehrsgünstig nahe den A7-Anschlussstellen Bahrenfeld und Othmarschen. Die S-Bahnhaltestelle Bahrenfeld ist nach 5 Minuten Fußweg erreicht und sichert eine gute Anbindung an das öffentliche Verkehrsnetz. Zahlreiche Geschäfte des täglichen Bedarfs, ein großer Edeka-Markt sowie diverse Cafés und Restaurants befinden sich nur wenige Meter entfernt im benachbarten Otto-von-Bahrenpark. Die vakante Bürofläche wird über ein modernes Foyer mit Personen- und Lastenaufzug erschlossen und verfügt zudem über einen weiteren, exklusiv zu nutzenden, ebenerdigen Eingang. Zur aktuellen Ausstattung zählen Linoleumfußboden, außen liegender Sonnenschutz, Beleuchtungssysteme, hohe Decken, eine CAT-7-Verkabelung, ein klimatisierter Serverraum, eine Pantry sowie getrennte WC-Einheiten. PKW-Stellplätze können direkt am Gebäude angemietet werden. Großzügige Lager- und Archivflächen stehen ebenfalls zur Verfügung.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['barrierefrei', 'lastenaufzug', 'erdgeschoss', 'stellplaetze']::text[], 169, 858, 'https://www.buerohamburg.de/objects/pdf/BHI_20121.pdf', null, 'filemaker', '20121') on conflict (id) do nothing;
